class Solution {
    public int minSwapsCouples(int[] row) {
        int[] position = new int[row.length];
        for (int i = 0; i < row.length; i++) {
            position[row[i]] = i;
        }

        int swaps = 0;
        for (int sofa = 0; sofa < row.length; sofa += 2) {
            int first = row[sofa];
            int partner = first ^ 1;
            if (row[sofa + 1] == partner) {
                continue;
            }
            int partnerIndex = position[partner];
            swap(row, sofa + 1, partnerIndex, position);
            swaps++;
        }
        return swaps;
    }

    private void swap(int[] row, int i, int j, int[] position) {
        int a = row[i];
        int b = row[j];
        row[i] = b;
        row[j] = a;
        position[a] = j;
        position[b] = i;
    }
}

class Solution {
    public int minSwapsCouples(int[] row) {
        int couples = row.length / 2;
        UnionFind uf = new UnionFind(couples);
        int components = couples;

        for (int sofa = 0; sofa < row.length; sofa += 2) {
            int leftCouple = row[sofa] / 2;
            int rightCouple = row[sofa + 1] / 2;
            if (uf.union(leftCouple, rightCouple)) {
                components--;
            }
        }
        return couples - components;
    }

    private static final class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        boolean union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return false;
            }
            if (size[rootA] < size[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
            return true;
        }
    }
}

