class Solution {
    public int minSwapsCouples(int[] row) {
        int couples = row.length / 2;
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < couples; i++) {
            graph.add(new ArrayList<>());
        }

        for (int sofa = 0; sofa < row.length; sofa += 2) {
            int a = row[sofa] / 2;
            int b = row[sofa + 1] / 2;
            if (a != b) {
                graph.get(a).add(b);
                graph.get(b).add(a);
            }
        }

        boolean[] seen = new boolean[couples];
        int swaps = 0;
        for (int couple = 0; couple < couples; couple++) {
            if (!seen[couple]) {
                int componentSize = dfs(couple, graph, seen);
                swaps += componentSize - 1;
            }
        }
        return swaps;
    }

    private int dfs(int couple, List<List<Integer>> graph, boolean[] seen) {
        if (seen[couple]) {
            return 0;
        }
        seen[couple] = true;
        int size = 1;
        for (int next : graph.get(couple)) {
            size += dfs(next, graph, seen);
        }
        return size;
    }
}

