class Solution {
    public int minSwapsCouples(int[] row) {
        int couples = row.length / 2;
        int[][] neighbors = new int[couples][2];
        int[] degree = new int[couples];
        for (int[] pair : neighbors) {
            Arrays.fill(pair, -1);
        }

        for (int sofa = 0; sofa < row.length; sofa += 2) {
            int a = row[sofa] / 2;
            int b = row[sofa + 1] / 2;
            if (a != b) {
                neighbors[a][degree[a]++] = b;
                neighbors[b][degree[b]++] = a;
            }
        }

        boolean[] seen = new boolean[couples];
        ArrayDeque<Integer> queue = new ArrayDeque<>();
        int swaps = 0;
        for (int start = 0; start < couples; start++) {
            if (seen[start]) {
                continue;
            }
            seen[start] = true;
            queue.add(start);
            int componentSize = 0;
            while (!queue.isEmpty()) {
                int current = queue.remove();
                componentSize++;
                for (int i = 0; i < degree[current]; i++) {
                    int next = neighbors[current][i];
                    if (!seen[next]) {
                        seen[next] = true;
                        queue.add(next);
                    }
                }
            }
            swaps += componentSize - 1;
        }
        return swaps;
    }
}
